VALUES ('10f00919-fec4-598b-8194-c39c433670b4', '3adedbdb-ac34-5459-97fd-7e8ae479ec3b', '999bacc2-a80e-5f3d-b0fb-f49945a25538', 'd0685907-814d-572d-8372-d36e54d0f220', 'Middle Name', 'Any middle or additional given names the person carries, when they are used officially. Optional; entered only when needed to tell people apart or to match identity documents and legal records. intrinsic person identity. identification. Up to 150 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
