VALUES ('bb5191d0-a71f-5f43-9f71-a6dd858e2dd5', 'f76e45c4-6ee7-5104-a0e9-91b749544c46', 'id', 'Id', 'The permanent system identity of the address. Generated on creation; parties, locations and document snapshots refer to the address through it.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
