VALUES ('e2f83877-55ef-5fb6-b5ae-49e37cd5d5f8', 'b54a7c3e-7261-500c-9608-5592c2cde4f4', 'id', 'Id', 'The identity of the location, which stays the same when its name or code changes. Generated on creation; assets, stock and documents refer to the location through it.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
