VALUES ('0df6e7be-1524-5af5-95db-5a77dae18eba', '053d544b-5d46-502b-af92-c7b33515bf1b', 'e2f83877-55ef-5fb6-b5ae-49e37cd5d5f8', '24575c1b-1993-5af1-ad87-a66ad3531b42', 'Id', 'The identity of the location, which stays the same when its name or code changes. Generated on creation; assets, stock and documents refer to the location through it. Must be unique: a save is rejected if another Location already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
