VALUES ('4a437071-f66c-5ad4-9483-40cef7a87ba6', '94c7633b-fd11-545b-8b14-1c0c1d0a66a9', '27886c9a-769f-5a78-91f7-9f76a56352ae', 'd0685907-814d-572d-8372-d36e54d0f220', 'Organization', 'The organisation the task is for. Chosen when it concerns a unit. At most one organisation. Groups tasks by unit.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
