VALUES ('f852bc2d-96d5-51e2-91ac-356e8ecc8f14', '5115185b-f8e3-5bc4-94d3-7edee0a2344c', '0d4942fb-afeb-58ad-8c46-2ea3279fd9b4', '24575c1b-1993-5af1-ad87-a66ad3531b42', 'Project Type', 'The kind of construction work. Chosen when the project is set up; drives templates, permits and risk checks. Construction of buildings such as offices, homes or factories. Roads, bridges, utilities and similar public works. General civil engineering such as earthworks and drainage. Plant, process facilities and heavy industrial structures. Refurbishment or extension of an existing structure. Work that fits none of the categories above. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('84fff7c1-b38c-5802-a83d-581d4c03bbcc', '5115185b-f8e3-5bc4-94d3-7edee0a2344c', '936d2d4d-0251-580b-be16-9149e3ad7631', 'd0685907-814d-572d-8372-d36e54d0f220', 'Site Condition', 'A description of the site''s physical conditions that affect the work, such as soil, access or contamination. Written after surveys; read by designers and contractors when planning and pricing. Up to 2000 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
