VALUES ('73201fc1-22ad-5304-a75c-8dd21d0604e4', '22001712-9ed7-5e66-8e93-90b4f9a4679e', '4a82ef64-eb24-5ec5-8682-3314090ce4ef', '24575c1b-1993-5af1-ad87-a66ad3531b42', 'Project Code', 'The code people use for the project, such as PRJ-0042. Unique; quoted in time booking, cost reports and invoices. Appears wherever work or cost is charged to the project. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Project already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
